css:
@keyframes riseIn{from{opacity:0;transform:translateY(28px)}to{opacity:1;transform:none}}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
@keyframes wipeIn{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0 0 0 0)}}
@keyframes kenburns{from{transform:translate3d(0,0,0) scale(1)}to{transform:translate3d(0,0,0) scale(1.028)}}
[data-kb]{will-change:transform;backface-visibility:hidden;transform:translate3d(0,0,0)}
[data-kb] image-slot{display:block;width:100%;height:100%}[data-kb] img{display:block;width:100%;height:100%}
section[data-deck-active] [data-kb]{animation:kenburns 26s linear both, fadeIn 1.2s ease-out both}
section[data-deck-active] [data-a]{animation-name:riseIn;animation-duration:.6s;animation-timing-function:cubic-bezier(.22,.85,.2,1);animation-fill-mode:both}
section[data-deck-active] [data-w]{animation-name:wipeIn;animation-duration:.8s;animation-timing-function:cubic-bezier(.2,.8,.2,1);animation-fill-mode:both}
html[data-motion="subtle"] section[data-deck-active] [data-a]{animation-name:fadeIn;animation-duration:.5s;animation-timing-function:ease-out}
html[data-motion="subtle"] section[data-deck-active] [data-kb]{animation:fadeIn .6s ease-out both}
section[data-deck-active] [data-a="2"],section[data-deck-active] [data-w="2"]{animation-delay:.12s}
section[data-deck-active] [data-a="3"],section[data-deck-active] [data-w="3"]{animation-delay:.24s}
section[data-deck-active] [data-a="4"],section[data-deck-active] [data-w="4"]{animation-delay:.36s}
section[data-deck-active] [data-a="5"],section[data-deck-active] [data-w="5"]{animation-delay:.48s}
section[data-deck-active] [data-a="6"],section[data-deck-active] [data-w="6"]{animation-delay:.6s}
section[data-deck-active] [data-a="7"],section[data-deck-active] [data-w="7"]{animation-delay:.72s}
section[data-deck-active] [data-a="8"],section[data-deck-active] [data-w="8"]{animation-delay:.84s}
section[data-deck-active] [data-a="9"],section[data-deck-active] [data-w="9"]{animation-delay:.96s}
html[data-motion="none"] [data-a],html[data-motion="none"] [data-w],html[data-motion="none"] [data-kb]{animation:none!important;opacity:1!important;transform:none!important;clip-path:none!important}
@media print{[data-a],[data-w],[data-kb]{animation:none!important;opacity:1!important;transform:none!important;clip-path:none!important}}

.deck-scale [data-kb]{animation:kenburns 26s linear both, fadeIn 1.2s ease-out both}
.deck-scale [data-a]{animation-name:riseIn;animation-duration:.6s;animation-timing-function:cubic-bezier(.22,.85,.2,1);animation-fill-mode:both}
.deck-scale [data-w]{animation-name:wipeIn;animation-duration:.8s;animation-timing-function:cubic-bezier(.2,.8,.2,1);animation-fill-mode:both}
html[data-motion="subtle"] .deck-scale [data-a]{animation-name:fadeIn;animation-duration:.5s;animation-timing-function:ease-out}
html[data-motion="subtle"] .deck-scale [data-kb]{animation:fadeIn .6s ease-out both}
.deck-scale [data-a="2"],.deck-scale [data-w="2"]{animation-delay:.12s}
.deck-scale [data-a="3"],.deck-scale [data-w="3"]{animation-delay:.24s}
.deck-scale [data-a="4"],.deck-scale [data-w="4"]{animation-delay:.36s}
.deck-scale [data-a="5"],.deck-scale [data-w="5"]{animation-delay:.48s}
.deck-scale [data-a="6"],.deck-scale [data-w="6"]{animation-delay:.6s}
.deck-scale [data-a="7"],.deck-scale [data-w="7"]{animation-delay:.72s}
.deck-scale [data-a="8"],.deck-scale [data-w="8"]{animation-delay:.84s}
.deck-scale [data-a="9"],.deck-scale [data-w="9"]{animation-delay:.96s}
